/**
 * The Rapid Rise AI logo mark, taken from https://www.rapidriseai.com/brand/.
 *
 * It is inlined rather than hotlinked so a parked domain never depends on the
 * main site staying up, and so the page makes no third-party requests.
 *
 * The Worker serves it from /logo.png with a long cache; the static build
 * inlines it as a data URI so the generated file stands on its own.
 */
export const LOGO_CONTENT_TYPE = 'image/png';

const LOGO_BASE64 =
  '';

export const LOGO_DATA_URI = `data:${LOGO_CONTENT_TYPE};base64,${LOGO_BASE64}`;

/** @type {Uint8Array | null} */
let cached = null;

/**
 * Decode the logo to raw bytes, once per isolate.
 *
 * @returns {Uint8Array}
 */
export function logoBytes() {
  if (cached) return cached;

  const binary = atob(LOGO_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }

  cached = bytes;
  return bytes;
}
